/**
 * VSA Academy - Mastermind Sovereign UI Engine (Elite Gemini Style)
 * ----------------------------------------------------------------
 */

:root {
    --ai-bg: #1e1f22;
    --ai-header: #2b2d30;
    --ai-border: #3c3f41;
    --ai-accent: #3574f0;
    --ai-text: #dfe1e5;
    --ai-muted: #afb1b3;
    --ai-success: #59a869;
    --ai-error: #f98a94;
    --ai-warning: #ebc40d;
}

/* 🧠 AI Widget & Button */
.ai-widget { position: fixed; bottom: 20px; left: 20px; z-index: 2000; display: flex; flex-direction: column; gap: 10px; }
.ai-btn { display: flex; width: 54px; height: 54px; background: var(--ai-accent); color: white; border-radius: 50%; align-items: center; justify-content: center; font-size: 26px; cursor: pointer; box-shadow: 0 8px 25px rgba(0,0,0,0.4); border: 1px solid rgba(255,255,255,0.1); }

/* 💬 Chat Box Structure */
.ai-chat-box { display: none; width: 820px; height: 600px; min-width: 400px; min-height: 400px; background: var(--ai-bg); border: 1px solid var(--ai-border); border-radius: 12px; box-shadow: 0 25px 60px rgba(0,0,0,0.6); overflow: hidden; position: relative; flex-direction: row; font-family: 'Inter', sans-serif; }
.ai-chat-box.maximized { width: 98vw !important; height: 98vh !important; border-radius: 0; top: 1vh !important; left: 1vw !important; }

.ai-main-content { flex-grow: 1; display: flex; flex-direction: column; height: 100%; overflow: hidden; }
.ai-messages { flex-grow: 1; padding: 20px; overflow-y: auto; display: flex; flex-direction: column; gap: 18px; }

/* 🎨 Advanced Input Wrapper (Gemini Style) */
.ai-input-container { padding: 15px; background: var(--ai-bg); border-top: 1px solid var(--ai-border); }
.ai-input-wrapper { background: #2b2d30; border: 1px solid #4e5157; border-radius: 18px; padding: 12px 16px; display: flex; flex-direction: column; gap: 8px; transition: border-color 0.2s; }
.ai-input-wrapper:focus-within { border-color: var(--ai-accent); }

#aiInput { width: 100%; background: transparent; border: none; color: var(--ai-text); font-size: 15px; line-height: 1.6; outline: none; resize: none; max-height: 250px; min-height: 24px; font-family: inherit; }

/* 🖼️ Fixed Attachment Previews (Image 1 Fix) */
#imagePreviewContainer { display: none; flex-wrap: wrap; gap: 12px; padding-bottom: 8px; border-bottom: none !important; } /* حذفت الخط */
.preview-item { position: relative; width: 55px; height: 55px; border-radius: 10px; overflow: hidden; border: 1px solid #4e5157; background: #141517; }
.preview-item img { width: 100%; height: 100%; object-fit: cover; }
.preview-item .remove-btn { position: absolute; top: -2px; right: -2px; background: rgba(0,0,0,0.8); color: white; border-radius: 50%; width: 18px; height: 18px; font-size: 10px; display: flex; align-items: center; justify-content: center; cursor: pointer; border: 1px solid #444; }

/* 🔘 Footer & Model Selector (Image 3 Style) */
.ai-input-footer { display: flex; justify-content: space-between; align-items: center; }
.ai-footer-icons { display: flex; gap: 16px; color: var(--ai-muted); }

/* زر الزائد المحترف (Gemini Style) */
.btn-plus-attachment {
    font-size: 24px !important;
    color: var(--ai-muted);
    cursor: pointer;
    transition: background 0.3s ease, color 0.2s;
    display: flex;
    align-items: center;
    justify-content: center;
    width: 32px;
    height: 32px;
    border-radius: 50%;
}

.btn-plus-attachment:hover {
    color: #fff;
    background: rgba(255, 255, 255, 0.05);
}

#modelSelector { background: #2b2d30 !important; color: var(--ai-text) !important; border: 1px solid #4e5157; border-radius: 6px; font-size: 12px; padding: 4px 8px; cursor: pointer; outline: none; }

.ai-send-btn-new { background: transparent; border: none; color: #4e5157; cursor: pointer; padding: 8px; transition: all 0.3s; border-radius: 50%; }
.ai-send-btn-new.active { background: var(--ai-accent); color: #fff; }

/* 🖼️ Images inside Chat (Image 4 Style) */
.chat-image-msg { max-width: 280px; border-radius: 12px; border: 1px solid var(--ai-border); margin: 8px 0; cursor: zoom-in; transition: transform 0.2s; }
.chat-image-msg:hover { transform: scale(1.02); }

/* 💬 Standard Messages */
.msg { max-width: 85%; padding: 12px 16px; border-radius: 16px; line-height: 1.6; }
.msg.user { background: #2b2d30; align-self: flex-end; border: 1px solid var(--ai-border); }
.msg.ai { background: transparent; align-self: flex-start; max-width: 95%; }

/* 📐 Resizers */
.ai-resizer { position: absolute; z-index: 1000; }
.ai-resizer-br { cursor: se-resize; right: 0; bottom: 0; width: 14px; height: 14px; }

